{{ silver_model_config('SEC_COMPANY_TICKER') }}

select
    cik,
    ticker,
    exchange,
    source_name,
    source_rank,
    last_sync_run_id,
    last_synced_at
from {{ source('edgartools_silver_landing', 'SEC_COMPANY_TICKER') }}
qualify row_number() over (
    partition by cik, ticker, source_name
    order by parse_sequence desc
) = 1
  and {{ silver_not_retired('sec_company_ticker', "concat_ws('|', cik, ticker, source_name)") }}
